double det = 0;
for (int i = 0; i < 3; i++) {
    mat<2, 2> submatrix;
    int sub_i = 0;
    for (int row = 1; row < 3; row++) {
        int sub_j = 0;
        for (int col = 0; col < 3; col++) {
            if (col == i) continue;
            submatrix[sub_i][sub_j] = m[row][col];
            sub_j++;
        }
        sub_i++;
    }
    double sign = (i % 2 == 0) ? 1.0 : -1.0;
    det += m[0][i] * sign * dt<2>::det(submatrix);
}
return det;

